  bookmarkListQuerySchema,
  readingStateSchema,
} from '../../shared/schemas.js';
import type { BookmarkRepository } from '../db/bookmark-repository.js';

export class DuplicateBookmarkError extends Error {
  public readonly statusCode = 409;
  public readonly code = 'DUPLICATE_URL';

  constructor(public readonly existingBookmark: Bookmark) {
    super('This web address is already saved in your library.');
  }
}

export class BookmarkNotFoundError extends Error {
  public readonly statusCode = 404;
  public readonly code = 'BOOKMARK_NOT_FOUND';

  constructor() {
    super('The requested bookmark was not found.');
  }
}

export class BookmarkService {
  constructor(private readonly repository: BookmarkRepository) {}

  createBookmark(input: BookmarkInput): Bookmark {
    const validated = bookmarkInputSchema.parse(input);
    const normalizedUrl = normalizeBookmarkUrl(validated.url);
    const tags = normalizeTags(validated.tags);

    const duplicate = this.repository.findDuplicate(normalizedUrl.urlKey);
    if (duplicate && !validated.allowDuplicate) throw new DuplicateBookmarkError(duplicate);

    return this.repository.create({
      url: normalizedUrl.url,
      urlKey: normalizedUrl.urlKey,
      title: validated.title,
      description: validated.description,
      tags,
      readingState: validated.readingState,
    });
  }

  replaceBookmark(bookmarkId: string, input: BookmarkInput): Bookmark {
    const id = bookmarkIdSchema.parse(bookmarkId);
    const validated = bookmarkInputSchema.parse(input);
    const normalizedUrl = normalizeBookmarkUrl(validated.url);
    const duplicate = this.repository.findDuplicate(normalizedUrl.urlKey, id);
    if (duplicate && !validated.allowDuplicate) throw new DuplicateBookmarkError(duplicate);

    const bookmark = this.repository.replace(id, {
      url: normalizedUrl.url,
      urlKey: normalizedUrl.urlKey,
      title: validated.title,
      description: validated.description,
      tags: normalizeTags(validated.tags),
      readingState: validated.readingState,
    });
    if (!bookmark) throw new BookmarkNotFoundError();
    return bookmark;
  }

  getBookmark(bookmarkId: string): Bookmark {
    const id = bookmarkIdSchema.parse(bookmarkId);
    const bookmark = this.repository.get(id);
    if (!bookmark) throw new BookmarkNotFoundError();
    return bookmark;
  }

  listBookmarks(query: BookmarkListQuery = {}): BookmarkList {
    const validated = bookmarkListQuerySchema.parse(query);
    const items = this.repository.list(validated);
    return { items, total: items.length };
  }

  listTags(): TagList {
    return { items: this.repository.listTags() };
  }

  deleteBookmark(bookmarkId: string): void {
    const id = bookmarkIdSchema.parse(bookmarkId);
    if (!this.repository.delete(id)) throw new BookmarkNotFoundError();
  }

  updateReadingState(bookmarkId: string, readingState: unknown): Bookmark {
    const id = bookmarkIdSchema.parse(bookmarkId);
    const state = readingStateSchema.parse(readingState);
    const bookmark = this.repository.updateReadingState(id, state);
    if (!bookmark) throw new BookmarkNotFoundError();
    return bookmark;
  }
}
import type { BookmarkDatabase } from './connection.js';
import type {
  Bookmark,
  ReadingState,
  ResolvedBookmarkListQuery,
  Tag,
} from '../../shared/contracts.js';
import { normalizeTagName, type NormalizedTag } from '../../shared/normalization.js';

interface BookmarkRow {
  id: string;
  url: string;
  title: string;
  description: string;
  reading_state: ReadingState;
  created_at: string;
  updated_at: string;
}

export interface CreateBookmarkRecord {
  url: string;
  urlKey: string;
  title: string;
  description: string;
  tags: NormalizedTag[];
  readingState: ReadingState;
}

export type ReplaceBookmarkRecord = CreateBookmarkRecord;

export interface BookmarkRepositoryOptions {
  now?: () => string;
  createId?: () => string;
}

const DEFAULT_QUERY: ResolvedBookmarkListQuery = {
  view: 'all',
  query: '',
  tag: [],
  sort: 'newest',
};

export class BookmarkRepository {
  private readonly now: () => string;
  private readonly createId: () => string;

  constructor(
    private readonly database: BookmarkDatabase,
    options: BookmarkRepositoryOptions = {},
  ) {
    this.now = options.now ?? (() => new Date().toISOString());
    this.createId = options.createId ?? (() => crypto.randomUUID());
  }

  private tagsForBookmark(bookmarkId: string): string[] {
    const rows = this.database
      .prepare(
        `SELECT t.display_name AS name
         FROM bookmark_tags bt
         JOIN tags t ON t.id = bt.tag_id
         WHERE bt.bookmark_id = ?
         ORDER BY bt.rowid ASC`,
      )
      .all(bookmarkId) as Array<{ name: string }>;
    return rows.map(({ name }) => name);
  }

  private mapRow(row: BookmarkRow): Bookmark {
    return {
      id: row.id,
      url: row.url,
      title: row.title,
      description: row.description,
      tags: this.tagsForBookmark(row.id),
      readingState: row.reading_state,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }

  get(bookmarkId: string): Bookmark | null {
    const row = this.database
      .prepare(
        `SELECT id, url, title, description, reading_state, created_at, updated_at
         FROM bookmarks WHERE id = ?`,
      )
      .get(bookmarkId) as BookmarkRow | undefined;
    return row ? this.mapRow(row) : null;
  }

  findDuplicate(urlKey: string, excludeId?: string): Bookmark | null {
    const row = this.database
      .prepare(
        `SELECT id, url, title, description, reading_state, created_at, updated_at
         FROM bookmarks
         WHERE url_key = ? AND (? IS NULL OR id <> ?)
         ORDER BY created_at ASC, id ASC
         LIMIT 1`,
      )
      .get(urlKey, excludeId ?? null, excludeId ?? null) as BookmarkRow | undefined;
    return row ? this.mapRow(row) : null;
  }

  create(record: CreateBookmarkRecord): Bookmark {
    const createTransaction = this.database.transaction(() => {
      const id = this.createId();
      const timestamp = this.now();
      this.database
        .prepare(
          `INSERT INTO bookmarks
           (id, url, url_key, title, description, reading_state, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          id,
          record.url,
          record.urlKey,
          record.title,
          record.description,
          record.readingState,
          timestamp,
          timestamp,
        );

      const findTag = this.database.prepare(
        'SELECT id FROM tags WHERE normalized_name = ?',
      );
      const insertTag = this.database.prepare(
        'INSERT INTO tags (id, display_name, normalized_name) VALUES (?, ?, ?)',
      );
      const attachTag = this.database.prepare(
        'INSERT INTO bookmark_tags (bookmark_id, tag_id) VALUES (?, ?)',
      );

      for (const tag of record.tags) {
        const existing = findTag.get(tag.normalizedName) as { id: string } | undefined;
        const tagId = existing?.id ?? this.createId();
        if (!existing) insertTag.run(tagId, tag.displayName, tag.normalizedName);
        attachTag.run(id, tagId);
      }

      return id;
    });

    const id = createTransaction();
    const bookmark = this.get(id);
    if (!bookmark) throw new Error('Created bookmark could not be loaded.');
    return bookmark;
  }

  replace(bookmarkId: string, record: ReplaceBookmarkRecord): Bookmark | null {
    const replaceTransaction = this.database.transaction(() => {
      const result = this.database
        .prepare(
          `UPDATE bookmarks
           SET url = ?, url_key = ?, title = ?, description = ?, reading_state = ?, updated_at = ?
           WHERE id = ?`,
        )
        .run(
          record.url,
          record.urlKey,
          record.title,
          record.description,
          record.readingState,
          this.now(),
          bookmarkId,
        );
      if (result.changes === 0) return false;

      this.database.prepare('DELETE FROM bookmark_tags WHERE bookmark_id = ?').run(bookmarkId);
      const findTag = this.database.prepare('SELECT id FROM tags WHERE normalized_name = ?');
      const insertTag = this.database.prepare(
        'INSERT INTO tags (id, display_name, normalized_name) VALUES (?, ?, ?)',
      );
      const attachTag = this.database.prepare(
        'INSERT INTO bookmark_tags (bookmark_id, tag_id) VALUES (?, ?)',
      );
      for (const tag of record.tags) {
        const existing = findTag.get(tag.normalizedName) as { id: string } | undefined;
        const tagId = existing?.id ?? this.createId();
        if (!existing) insertTag.run(tagId, tag.displayName, tag.normalizedName);
        attachTag.run(bookmarkId, tagId);
      }
      this.database.prepare(
        'DELETE FROM tags WHERE NOT EXISTS (SELECT 1 FROM bookmark_tags WHERE tag_id = tags.id)',
      ).run();
      return true;
    });

    return replaceTransaction() ? this.get(bookmarkId) : null;
  }

  list(query: ResolvedBookmarkListQuery = DEFAULT_QUERY): Bookmark[] {
    const conditions: string[] = [];
    const parameters: Array<string | number> = [];

    if (query.view === 'read-later') conditions.push("b.reading_state = 'to_read'");

    if (query.query) {
      const escaped = query.query.toLowerCase().replaceAll('\\', '\\\\').replaceAll('%', '\\%').replaceAll('_', '\\_');
      const pattern = `%${escaped}%`;
      conditions.push(`(
        lower(b.title) LIKE ? ESCAPE '\\' OR
        lower(b.url) LIKE ? ESCAPE '\\' OR
        lower(b.description) LIKE ? ESCAPE '\\' OR
        EXISTS (
          SELECT 1 FROM bookmark_tags search_bt
          JOIN tags search_t ON search_t.id = search_bt.tag_id
          WHERE search_bt.bookmark_id = b.id
            AND lower(search_t.display_name) LIKE ? ESCAPE '\\'
        )
      )`);
      parameters.push(pattern, pattern, pattern, pattern);
    }

    for (const tag of query.tag) {
      conditions.push(`EXISTS (
        SELECT 1 FROM bookmark_tags filter_bt
        JOIN tags filter_t ON filter_t.id = filter_bt.tag_id
        WHERE filter_bt.bookmark_id = b.id AND filter_t.normalized_name = ?
      )`);
      parameters.push(normalizeTagName(tag));
    }

    const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
    const order =
      query.sort === 'oldest'
        ? 'b.created_at ASC, b.id ASC'
        : query.sort === 'title'
          ? 'lower(b.title) ASC, b.id ASC'
          : 'b.created_at DESC, b.id ASC';

    const rows = this.database
      .prepare(
        `SELECT b.id, b.url, b.title, b.description, b.reading_state, b.created_at, b.updated_at
         FROM bookmarks b ${where}
         ORDER BY ${order}`,
      )
      .all(...parameters) as BookmarkRow[];
    return rows.map((row) => this.mapRow(row));
  }

  listTags(): Tag[] {
    return this.database
      .prepare(
        `SELECT t.display_name AS name,
                t.normalized_name AS normalizedName,
                COUNT(bt.bookmark_id) AS bookmarkCount
         FROM tags t
         JOIN bookmark_tags bt ON bt.tag_id = t.id
         GROUP BY t.id, t.display_name, t.normalized_name
         HAVING COUNT(bt.bookmark_id) > 0
         ORDER BY lower(t.display_name) ASC, t.normalized_name ASC`,
      )
      .all() as Tag[];
  }

  delete(bookmarkId: string): boolean {
    const remove = this.database.transaction(() => {
      const result = this.database.prepare('DELETE FROM bookmarks WHERE id = ?').run(bookmarkId);
      if (result.changes > 0) {
        this.database.prepare(
          'DELETE FROM tags WHERE NOT EXISTS (SELECT 1 FROM bookmark_tags WHERE tag_id = tags.id)',
        ).run();
      }
      return result.changes > 0;
    });
    return remove();
  }

  updateReadingState(bookmarkId: string, readingState: ReadingState): Bookmark | null {
    const result = this.database
      .prepare(
        `UPDATE bookmarks
         SET reading_state = ?, updated_at = ?
         WHERE id = ?`,
      )
      .run(readingState, this.now(), bookmarkId);
    return result.changes > 0 ? this.get(bookmarkId) : null;
  }
}
import { Component, useCallback, useEffect, useState, type ErrorInfo, type ReactNode } from 'react';

import type { Bookmark, Tag } from '../shared/contracts.js';
import {
  deleteBookmark,
  listBookmarks,
  updateBookmarkReadingState,
} from './api/bookmarks.js';
import { listTags } from './api/tags.js';
import { BookmarkForm } from './features/bookmarks/BookmarkForm.js';
import { BookmarkList } from './features/bookmarks/BookmarkList.js';
import { LibraryTabs } from './features/bookmarks/LibraryTabs.js';
import { LibraryControls } from './features/bookmarks/LibraryControls.js';
import { useLibraryView } from './features/bookmarks/useLibraryView.js';

export function App() {
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingBookmark, setEditingBookmark] = useState<Bookmark | undefined>();
  const [tags, setTags] = useState<Tag[]>([]);
  const {
    view,
    query,
    tags: selectedTags,
    sort,
    setView,
    setQuery,
    setTags: setSelectedTags,
    setSort,
    clearCriteria,
  } = useLibraryView();

  const load = useCallback(async () => {
    try {
      const result = await listBookmarks({ view, query, tag: selectedTags, sort });
      setBookmarks(result.items);
      setLoaded(true);
      setErrorMessage('');
    } catch {
      setErrorMessage('Your bookmarks could not be loaded.');
    }
  }, [query, selectedTags, sort, view]);

  const loadTags = useCallback(async () => {
    try {
      setTags((await listTags()).items);
    } catch {
      // Bookmark data remains usable when the supporting tag list cannot refresh.
    }
  }, []);

  useEffect(() => {
    void load();
    void loadTags();
  }, [load, loadTags]);

  const handleSaved = (_bookmark: Bookmark) => {
    setLoaded(true);
    setErrorMessage('');
    setShowForm(false);
    setEditingBookmark(undefined);
    void load();
    void loadTags();
    window.setTimeout(() => document.getElementById('library-tab')?.focus(), 0);
  };

  const handleDelete = async (bookmark: Bookmark) => {
    try {
      await deleteBookmark(bookmark.id);
      await Promise.all([load(), loadTags()]);
      window.setTimeout(() => document.getElementById('library-tab')?.focus(), 0);
    } catch {
      setErrorMessage('The bookmark could not be deleted.');
    }
  };

  const handleReadingStateChange = async (
    bookmark: Bookmark,
    readingState: Bookmark['readingState'],
  ) => {
    try {
      const updated = await updateBookmarkReadingState(bookmark.id, readingState);
      setBookmarks((current) =>
        view === 'read-later' && updated.readingState !== 'to_read'
          ? current.filter(({ id }) => id !== updated.id)
          : current.map((item) => (item.id === updated.id ? updated : item)),
      );
      setErrorMessage('');
    } catch {
      setErrorMessage('The reading status could not be changed.');
    }
  };

  return (
    <main {...(loaded ? { 'data-harness-ready': 'true' } : {})}>
      <header>
        <a href="/" aria-label="Trove home">Trove</a>
        <div>
          <p>Personal bookmark library</p>
          <h1>Your bookmarks, kept close.</h1>
          <p>Save useful corners of the web and return when the time is right.</p>
        </div>
        <button
          type="button"
          onClick={() => {
            setEditingBookmark(undefined);
            setShowForm(true);
          }}
        >
          Add bookmark
        </button>
      </header>

      {showForm && (
        <section aria-labelledby="add-bookmark-heading">
          <h2 id="add-bookmark-heading">
            {editingBookmark ? 'Edit bookmark' : 'Add a bookmark'}
          </h2>
          <BookmarkForm
            key={editingBookmark?.id ?? 'create'}
            bookmark={editingBookmark}
            onSaved={handleSaved}
            onCancel={() => {
              setShowForm(false);
              setEditingBookmark(undefined);
            }}
          />
        </section>
      )}

      <LibraryTabs view={view} onChange={setView} />

      <LibraryControls
        query={query}
        selectedTags={selectedTags}
        sort={sort}
        tags={tags}
        onQueryChange={setQuery}
        onTagsChange={setSelectedTags}
        onSortChange={setSort}
      />

      <section
        id={view === 'all' ? 'library-tab-panel' : 'read-later-tab-panel'}
        role="tabpanel"
        aria-labelledby={view === 'all' ? 'library-tab' : 'read-later-tab'}
      >
        <div>
          <p>Collection</p>
          <h2>{view === 'all' ? 'Library' : 'Read Later'}</h2>
          {loaded && <p>{bookmarks.length} saved</p>}
        </div>

        {!loaded && !errorMessage && (
          <p role="status" aria-live="polite">
            Loading your bookmarks…
          </p>
        )}

        {errorMessage && (
          <div role="alert">
            <p>{errorMessage}</p>
            <button type="button" onClick={() => void load()}>
              Try again
            </button>
          </div>
        )}

        {loaded && (
          <BookmarkList
            bookmarks={bookmarks}
            emptyState={
              query || selectedTags.length > 0
                ? 'no-results'
                : view === 'read-later'
                  ? 'read-later'
                  : 'library'
            }
            onClearCriteria={clearCriteria}
            onReadingStateChange={(bookmark, readingState) =>
              void handleReadingStateChange(bookmark, readingState)
            }
            onEdit={(bookmark) => {
              setEditingBookmark(bookmark);
              setShowForm(true);
            }}
            onDelete={(bookmark) => void handleDelete(bookmark)}
          />
        )}
      </section>
    </main>
  );
}

interface AppErrorBoundaryProps {
  children: ReactNode;
}

interface AppErrorBoundaryState {
  hasError: boolean;
}

export class AppErrorBoundary extends Component<
  AppErrorBoundaryProps,
  AppErrorBoundaryState
> {
  public state: AppErrorBoundaryState = { hasError: false };

  public static getDerivedStateFromError(): AppErrorBoundaryState {
    return { hasError: true };
  }

  public componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error('The bookmark application could not be rendered.', error, info);
  }

  public render(): ReactNode {
    if (this.state.hasError) {
      return (
        <main>
          <h1>Trove</h1>
          <div role="alert">
            <h2>Something went wrong</h2>
            <p>Refresh the page to return to your bookmarks.</p>
          </div>
        </main>
      );
    }

    return this.props.children;
  }
}

export default App;
import { useEffect, useState } from 'react';

import type { SortOrder, Tag } from '../../../shared/contracts.js';

export interface LibraryControlsProps {
  query: string;
  selectedTags: readonly string[];
  sort: SortOrder;
  tags: readonly Tag[];
  onQueryChange: (query: string) => void;
  onTagsChange: (tags: string[]) => void;
  onSortChange: (sort: SortOrder) => void;
}

export function LibraryControls({
  query,
  selectedTags,
  sort,
  tags,
  onQueryChange,
  onTagsChange,
  onSortChange,
}: LibraryControlsProps) {
  const [draftQuery, setDraftQuery] = useState(query);

  useEffect(() => setDraftQuery(query), [query]);
  useEffect(() => {
    if (draftQuery === query) return;
    const timer = window.setTimeout(() => onQueryChange(draftQuery), 250);
    return () => window.clearTimeout(timer);
  }, [draftQuery, onQueryChange, query]);

  const toggleTag = (normalizedName: string, selected: boolean) => {
    onTagsChange(
      selected
        ? [...selectedTags, normalizedName]
        : selectedTags.filter((tag) => tag !== normalizedName),
    );
  };

  return (
    <section aria-label="Find and organize bookmarks">
      <label htmlFor="bookmark-search">Search bookmarks</label>
      <input
        id="bookmark-search"
        type="search"
        value={draftQuery}
        onChange={(event) => setDraftQuery(event.target.value)}
      />

      {tags.length > 0 && (
        <fieldset>
          <legend>Filter by tags</legend>
          {tags.map((tag) => (
            <label key={tag.normalizedName}>
              <input
                type="checkbox"
                checked={selectedTags.includes(tag.normalizedName)}
                onChange={(event) => toggleTag(tag.normalizedName, event.target.checked)}
              />
              {tag.name} ({tag.bookmarkCount})
            </label>
          ))}
        </fieldset>
      )}

      <label htmlFor="bookmark-sort">Sort bookmarks</label>
      <select
        id="bookmark-sort"
        value={sort}
        onChange={(event) => onSortChange(event.target.value as SortOrder)}
      >
        <option value="newest">Newest saved</option>
        <option value="oldest">Oldest saved</option>
        <option value="title">Title A–Z</option>
      </select>

      {selectedTags.length > 0 && (
        <div aria-label="Active filters">
          {selectedTags.map((normalizedName) => {
            const label = tags.find((tag) => tag.normalizedName === normalizedName)?.name ?? normalizedName;
            return (
              <button
                key={normalizedName}
                type="button"
                aria-label={`Remove ${label} filter`}
                onClick={() => toggleTag(normalizedName, false)}
              >
                {label} ×
              </button>
            );
          })}
        </div>
      )}
    </section>
  );
}
import type { Bookmark } from '../../../shared/contracts.js';
import type { ReadingState } from '../../../shared/contracts.js';
import { BookmarkCard } from './BookmarkCard.js';

export type BookmarkListEmptyState = 'library' | 'read-later' | 'no-results';

export interface BookmarkListProps {
  bookmarks: readonly Bookmark[];
  emptyState?: BookmarkListEmptyState;
  onClearCriteria?: () => void;
  onReadingStateChange?: (bookmark: Bookmark, readingState: ReadingState) => void;
  onEdit?: (bookmark: Bookmark) => void;
  onDelete?: (bookmark: Bookmark) => void;
}

interface EmptyStateCopy {
  title: string;
  description: string;
}

const emptyStateCopy: Record<BookmarkListEmptyState, EmptyStateCopy> = {
  library: {
    title: 'Your library is empty',
    description: 'Save your first bookmark to start building your collection.',
  },
  'read-later': {
    title: 'Nothing to read later',
    description: 'Bookmarks marked To Read will appear here.',
  },
  'no-results': {
    title: 'No bookmarks match your search',
    description: 'Try changing or clearing your search and filters.',
  },
};

function BookmarkListEmpty({
  state,
  onClearCriteria,
}: {
  state: BookmarkListEmptyState;
  onClearCriteria?: () => void;
}) {
  const copy = emptyStateCopy[state];

  return (
    <section role="status" aria-labelledby="bookmark-empty-heading">
      <h3 id="bookmark-empty-heading">{copy.title}</h3>
      <p>{copy.description}</p>
      {state === 'no-results' && onClearCriteria && (
        <button type="button" onClick={onClearCriteria}>
          Clear search and filters
        </button>
      )}
    </section>
  );
}

export function BookmarkList({
  bookmarks,
  emptyState = 'library',
  onClearCriteria,
  onReadingStateChange,
  onEdit,
  onDelete,
}: BookmarkListProps) {
  if (bookmarks.length === 0) {
    return <BookmarkListEmpty state={emptyState} onClearCriteria={onClearCriteria} />;
  }

  return (
    <ul aria-label="Bookmarks">
      {bookmarks.map((bookmark) => (
        <li key={bookmark.id}>
          <BookmarkCard
            bookmark={bookmark}
            onReadingStateChange={onReadingStateChange}
            onEdit={onEdit}
            onDelete={onDelete}
          />
        </li>
      ))}
    </ul>
  );
}

