interface TemporaryDatabaseOptions {
  migrate?: boolean;
  migrationDirectory?: string;
  now?: () => string;
}

export interface TemporaryDatabase {
  database: BookmarkDatabase;
  databasePath: string;
  directory: string;
  openConnection: (migrate?: boolean) => BookmarkDatabase;
  cleanup: () => void;
}

/**
 * Create a file-backed database in an isolated directory. Every connection
 * opened through the fixture is tracked and safely closed during cleanup.
 */
export function createTemporaryDatabase(
  options: TemporaryDatabaseOptions = {},
): TemporaryDatabase {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'bookmark-manager-test-'));
  const databasePath = path.join(directory, 'bookmarks.sqlite');
  const migrationDirectory =
    options.migrationDirectory ?? path.resolve(process.cwd(), 'migrations');
  const connections = new Set<BookmarkDatabase>();

  const openConnection = (migrate = options.migrate ?? true): BookmarkDatabase => {
    const database = openDatabase(databasePath);
    connections.add(database);
    if (migrate) runMigrations(database, migrationDirectory, options.now);
    return database;
  };

  const database = openConnection();

  return {
    database,
    databasePath,
    directory,
    openConnection,
    cleanup: () => {
      for (const connection of connections) closeDatabase(connection);
      fs.rmSync(directory, { recursive: true, force: true });
    },
  };
}
import fs from 'node:fs';
import path from 'node:path';
import Database from 'better-sqlite3';

export type BookmarkDatabase = Database.Database;

export interface DatabaseOptions {
  readonly?: boolean;
  fileMustExist?: boolean;
}

export function openDatabase(databasePath: string, options: DatabaseOptions = {}): BookmarkDatabase {
  if (databasePath !== ':memory:') {
    fs.mkdirSync(path.dirname(databasePath), { recursive: true });
  }

  const database = new Database(databasePath, {
    readonly: options.readonly ?? false,
    fileMustExist: options.fileMustExist ?? false,
    timeout: 5_000,
  });

  database.pragma('foreign_keys = ON');
  if (!options.readonly && databasePath !== ':memory:') {
    database.pragma('journal_mode = WAL');
  }
  database.pragma('busy_timeout = 5000');

  return database;
}

export function closeDatabase(database: BookmarkDatabase): void {
  if (database.open) database.close();
}
import fs from 'node:fs';
import path from 'node:path';
import type { BookmarkDatabase } from './connection.js';

const MIGRATION_PATTERN = /^(\d+)_([a-z0-9_-]+)\.sql$/i;

interface Migration {
  version: number;
  name: string;
  sql: string;
}

function loadMigrations(directory: string): Migration[] {
  return fs
    .readdirSync(directory)
    .map((filename) => {
      const match = filename.match(MIGRATION_PATTERN);
      if (!match) return null;
      return {
        version: Number(match[1]),
        name: match[2],
        sql: fs.readFileSync(path.join(directory, filename), 'utf8'),
      };
    })
    .filter((migration): migration is Migration => migration !== null)
    .sort((a, b) => a.version - b.version);
}

export function runMigrations(
  database: BookmarkDatabase,
  directory = path.resolve(process.cwd(), 'migrations'),
  now: () => string = () => new Date().toISOString(),
): void {
  database.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      version INTEGER PRIMARY KEY,
      name TEXT NOT NULL,
      applied_at TEXT NOT NULL
    ) STRICT;
  `);

  const applied = new Set(
    (database.prepare('SELECT version FROM schema_migrations').all() as Array<{ version: number }>).map(
      ({ version }) => version,
    ),
  );

  const apply = database.transaction((migration: Migration) => {
    database.exec(migration.sql);
    database
      .prepare('INSERT INTO schema_migrations (version, name, applied_at) VALUES (?, ?, ?)')
      .run(migration.version, migration.name, now());
  });

  for (const migration of loadMigrations(directory)) {
    if (!applied.has(migration.version)) apply(migration);
  }
}
