import path from 'node:path';
import type { BookmarkDatabase } from './connection.js';

const MIGRATION_PATTERN = /^(\d+)_([a-z0-9_-]+)\.sql$/i;

interface Migration {
  version: number;
  name: string;
  sql: string;
}

function loadMigrations(directory: string): Migration[] {
  return fs
    .readdirSync(directory)
    .map((filename) => {
      const match = filename.match(MIGRATION_PATTERN);
      if (!match) return null;
      return {
        version: Number(match[1]),
        name: match[2],
        sql: fs.readFileSync(path.join(directory, filename), 'utf8'),
      };
    })
    .filter((migration): migration is Migration => migration !== null)
    .sort((a, b) => a.version - b.version);
}

export function runMigrations(
  database: BookmarkDatabase,
  directory = path.resolve(process.cwd(), 'migrations'),
  now: () => string = () => new Date().toISOString(),
): void {
  database.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      version INTEGER PRIMARY KEY,
      name TEXT NOT NULL,
      applied_at TEXT NOT NULL
    ) STRICT;
  `);

  const applied = new Set(
    (database.prepare('SELECT version FROM schema_migrations').all() as Array<{ version: number }>).map(
      ({ version }) => version,
    ),
  );

  const apply = database.transaction((migration: Migration) => {
    database.exec(migration.sql);
    database
      .prepare('INSERT INTO schema_migrations (version, name, applied_at) VALUES (?, ?, ?)')
      .run(migration.version, migration.name, now());
  });

  for (const migration of loadMigrations(directory)) {
    if (!applied.has(migration.version)) apply(migration);
  }
}
CREATE TABLE IF NOT EXISTS bookmarks (
  id TEXT PRIMARY KEY,
  url TEXT NOT NULL CHECK(length(url) BETWEEN 1 AND 4096),
  url_key TEXT NOT NULL CHECK(length(url_key) BETWEEN 1 AND 4096),
  title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 300),
  description TEXT NOT NULL DEFAULT '' CHECK(length(description) <= 2000),
  reading_state TEXT NOT NULL DEFAULT 'untracked'
    CHECK(reading_state IN ('untracked', 'to_read', 'read')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
) STRICT;

CREATE TABLE IF NOT EXISTS tags (
  id TEXT PRIMARY KEY,
  display_name TEXT NOT NULL CHECK(length(trim(display_name)) BETWEEN 1 AND 40),
  normalized_name TEXT NOT NULL UNIQUE CHECK(length(normalized_name) BETWEEN 1 AND 40)
) STRICT;

CREATE TABLE IF NOT EXISTS bookmark_tags (
  bookmark_id TEXT NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
  tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
  PRIMARY KEY (bookmark_id, tag_id)
) STRICT;

CREATE TABLE IF NOT EXISTS schema_migrations (
  version INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  applied_at TEXT NOT NULL
) STRICT;

CREATE INDEX IF NOT EXISTS idx_bookmarks_url_key
  ON bookmarks(url_key);

CREATE INDEX IF NOT EXISTS idx_bookmarks_reading_created
  ON bookmarks(reading_state, created_at, id);

CREATE INDEX IF NOT EXISTS idx_bookmarks_created
  ON bookmarks(created_at, id);

CREATE INDEX IF NOT EXISTS idx_bookmark_tags_tag_bookmark
  ON bookmark_tags(tag_id, bookmark_id);
import { useCallback, useEffect, useState } from 'react';

import type { BookmarkListView, SortOrder } from '../../../shared/contracts.js';

interface LibraryViewState {
  view: BookmarkListView;
  query: string;
  tags: string[];
  sort: SortOrder;
}

function readState(): LibraryViewState {
  const parameters = new URLSearchParams(window.location.search);
  const rawSort = parameters.get('sort');
  return {
    view: parameters.get('view') === 'read-later' ? 'read-later' : 'all',
    query: parameters.get('query') ?? '',
    tags: parameters.getAll('tag'),
    sort: rawSort === 'oldest' || rawSort === 'title' ? rawSort : 'newest',
  };
}

function writeState(state: LibraryViewState, push = false): void {
  const parameters = new URLSearchParams();
  if (state.view === 'read-later') parameters.set('view', state.view);
  if (state.query) parameters.set('query', state.query);
  for (const tag of state.tags) parameters.append('tag', tag);
  if (state.sort !== 'newest') parameters.set('sort', state.sort);
  const search = parameters.toString();
  window.history[push ? 'pushState' : 'replaceState'](
    {},
    '',
    `${window.location.pathname}${search ? `?${search}` : ''}`,
  );
}

export function useLibraryView() {
  const [state, setState] = useState<LibraryViewState>(readState);

  useEffect(() => {
    const handlePopState = () => setState(readState());
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const update = useCallback(
    (changes: Partial<LibraryViewState>, push = false) => {
      setState((current) => {
        const next = { ...current, ...changes };
        writeState(next, push);
        return next;
      });
    },
    [],
  );

  return {
    ...state,
    setView: (view: BookmarkListView) => update({ view }, true),
    setQuery: (query: string) => update({ query }),
    setTags: (tags: string[]) => update({ tags }),
    setSort: (sort: SortOrder) => update({ sort }),
    clearCriteria: () => update({ query: '', tags: [] }),
  };
}
import type {
  Bookmark,
  BookmarkInput,
  BookmarkList,
  BookmarkListQuery,
  DuplicateErrorResponse,
  ErrorResponse,
  FieldErrors,
  ReadingState,
  TagList,
} from '../../shared/contracts.js';

export interface ApiRequestOptions {
  signal?: AbortSignal;
}

interface ApiErrorOptions {
  status: number;
  code: string;
  fieldErrors?: FieldErrors;
  cause?: unknown;
}

export class ApiError extends Error {
  readonly status: number;
  readonly code: string;
  readonly fieldErrors?: FieldErrors;

  constructor(message: string, options: ApiErrorOptions) {
    super(message, { cause: options.cause });
    this.name = 'ApiError';
    this.status = options.status;
    this.code = options.code;
    this.fieldErrors = options.fieldErrors;
  }
}

export class DuplicateBookmarkApiError extends ApiError {
  readonly existingBookmark: Bookmark;

  constructor(response: DuplicateErrorResponse, status = 409) {
    super(response.error.message, {
      status,
      code: response.error.code,
    });
    this.name = 'DuplicateBookmarkApiError';
    this.existingBookmark = response.existingBookmark;
  }
}

export function isApiError(error: unknown): error is ApiError {
  return error instanceof ApiError;
}

export function isDuplicateBookmarkError(
  error: unknown,
): error is DuplicateBookmarkApiError {
  return error instanceof DuplicateBookmarkApiError;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const isBookmark = (value: unknown): value is Bookmark =>
  isRecord(value) &&
  typeof value.id === 'string' &&
  typeof value.url === 'string' &&
  typeof value.title === 'string' &&
  typeof value.description === 'string' &&
  Array.isArray(value.tags) &&
  value.tags.every((tag) => typeof tag === 'string') &&
  (value.readingState === 'untracked' ||
    value.readingState === 'to_read' ||
    value.readingState === 'read') &&
  typeof value.createdAt === 'string' &&
  typeof value.updatedAt === 'string';

const asFieldErrors = (value: unknown): FieldErrors | undefined => {
  if (!isRecord(value)) return undefined;
  const entries = Object.entries(value);
  if (!entries.every(([, message]) => typeof message === 'string')) return undefined;
  return Object.fromEntries(entries) as FieldErrors;
};

const asErrorResponse = (value: unknown): ErrorResponse | null => {
  if (!isRecord(value) || !isRecord(value.error)) return null;
  const { code, message, fieldErrors } = value.error;
  if (typeof code !== 'string' || typeof message !== 'string') return null;
  const parsedFieldErrors = asFieldErrors(fieldErrors);

  return {
    error: {
      code,
      message,
      ...(parsedFieldErrors !== undefined ? { fieldErrors: parsedFieldErrors } : {}),
    },
  };
};

const asDuplicateResponse = (value: unknown): DuplicateErrorResponse | null => {
  if (
    !isRecord(value) ||
    !isRecord(value.error) ||
    value.error.code !== 'DUPLICATE_URL' ||
    typeof value.error.message !== 'string' ||
    !isBookmark(value.existingBookmark)
  ) {
    return null;
  }

  return {
    error: {
      code: 'DUPLICATE_URL',
      message: value.error.message,
    },
    existingBookmark: value.existingBookmark,
  };
};

async function readJson(response: Response): Promise<unknown> {
  const text = await response.text();
  if (text === '') return undefined;

  try {
    return JSON.parse(text) as unknown;
  } catch (cause) {
    throw new ApiError('The server returned an invalid response.', {
      status: response.status,
      code: 'INVALID_RESPONSE',
      cause,
    });
  }
}

/** Shared same-origin JSON transport used by the bookmark and metadata APIs. */
export async function requestJson<T>(
  path: string,
  init: RequestInit = {},
): Promise<T> {
  const headers = new Headers(init.headers);
  if (!headers.has('accept')) headers.set('accept', 'application/json');

  let response: Response;
  try {
    response = await fetch(path, {
      ...init,
      credentials: 'same-origin',
      headers,
    });
  } catch (cause) {
    if (init.signal?.aborted) throw cause;
    throw new ApiError('The server could not be reached.', {
      status: 0,
      code: 'NETWORK_ERROR',
      cause,
    });
  }
  const body = await readJson(response);

  if (!response.ok) {
    const duplicate = asDuplicateResponse(body);
    if (response.status === 409 && duplicate !== null) {
      throw new DuplicateBookmarkApiError(duplicate, response.status);
    }

    const structured = asErrorResponse(body);
    throw new ApiError(
      structured?.error.message ||
        response.statusText ||
        `The request failed with status ${response.status}.`,
      {
        status: response.status,
        code: structured?.error.code ?? 'HTTP_ERROR',
        fieldErrors: structured?.error.fieldErrors,
      },
    );
  }

  if (body === undefined && response.status !== 204) {
    throw new ApiError('The server returned an empty response.', {
      status: response.status,
      code: 'INVALID_RESPONSE',
    });
  }

  return body as T;
}

const jsonRequest = (method: string, body: unknown, signal?: AbortSignal): RequestInit => ({
  method,
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify(body),
  signal,
});

export async function listBookmarks(
  query: BookmarkListQuery = {},
  options: ApiRequestOptions = {},
): Promise<BookmarkList> {
  const parameters = new URLSearchParams();
  if (query.view !== undefined) parameters.set('view', query.view);
  if (query.query !== undefined && query.query !== '') parameters.set('query', query.query);
  for (const tag of query.tag ?? []) parameters.append('tag', tag);
  if (query.sort !== undefined) parameters.set('sort', query.sort);

  const suffix = parameters.size === 0 ? '' : `?${parameters.toString()}`;
  return requestJson<BookmarkList>(`/api/bookmarks${suffix}`, {
    signal: options.signal,
  });
}

export function createBookmark(
  input: BookmarkInput,
  options: ApiRequestOptions = {},
): Promise<Bookmark> {
  return requestJson<Bookmark>(
    '/api/bookmarks',
    jsonRequest('POST', input, options.signal),
  );
}

export function getBookmark(
  bookmarkId: string,
  options: ApiRequestOptions = {},
): Promise<Bookmark> {
  return requestJson<Bookmark>(`/api/bookmarks/${encodeURIComponent(bookmarkId)}`, {
    signal: options.signal,
  });
}

export function replaceBookmark(
  bookmarkId: string,
  input: BookmarkInput,
  options: ApiRequestOptions = {},
): Promise<Bookmark> {
  return requestJson<Bookmark>(
    `/api/bookmarks/${encodeURIComponent(bookmarkId)}`,
    jsonRequest('PUT', input, options.signal),
  );
}
